function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || nums1.length < 1 || nums1.length > 100) return 'nums1 needs 1 to 100 values.';
  if (!Array.isArray(nums2) || nums2.length < 1 || nums2.length > 100) return 'nums2 needs 1 to 100 values.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Every value is a whole number from 1 to 100.';
  return null;
}

