function findIntersectionValues(nums1, nums2) {
  const occurs = (value, list) => {
    for (let k = 0; k < list.length; k++) if (list[k] === value) return true;
    return false;
  };
  let first = 0, second = 0;
  for (let i = 0; i < nums1.length; i++) if (occurs(nums1[i], nums2)) first++;
  for (let j = 0; j < nums2.length; j++) if (occurs(nums2[j], nums1)) second++;
  return [first, second];
}

