function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 1 + Math.floor(rand() * 8);
  const m = large ? 100 : 1 + Math.floor(rand() * 8);
  const span = large ? 100 : (rand() < 0.5 ? 5 : 100);
  // Large inputs sometimes draw nums2 from 51..100 only, so the overlap is partial.
  const low2 = large && rand() < 0.5 ? 51 : 1;
  const nums1 = Array.from({ length: n }, () => 1 + Math.floor(rand() * span));
  const nums2 = Array.from({ length: m }, () => low2 + Math.floor(rand() * (span - low2 + 1)));
  return [nums1, nums2];
}
